551			const value = option.arity === "value" ? tokens[index + 1]?.text : undefined;
552			const optionWithValue = value === undefined ? token.text : `${token.text} ${value}`;
553			warnings.push(
554				`${optionWithValue} was included in the prompt body. To specify an argument or an option, place it at the beginning of the command input: /${command} ${optionWithValue} ${firstProseWord} …`,
555			);
556		}
557		return warnings;
558	}
559	
560	function unescapeWord(word: string): string {
561		if (!word.startsWith("\\-")) return word;
562		const unescaped = word.slice(1);
563		return unescaped.startsWith("-\\-") ? `-${unescaped.slice(2)}` : unescaped;
564	}
565	
566	function unescapeProse(prose: string, quoteMask: boolean[]): string {
567		return prose.replace(/\S+/g, (word, offset: number) =>
568			quoteMask[offset] ? word : unescapeWord(word),
569		);
570	}
571	
